<script lang="ts">import {onMount} from 'svelte';import Heading from '$lib/components/Heading.svelte';import {palettes} from '$lib/navigation';let tab='Account',palette='original',dark=false;onMount(()=>{try{palette=localStorage.getItem('drevanta-svelte-palette')||'original';dark=localStorage.getItem('drevanta-svelte-mode')==='dark'}catch{}});function apply(p:string,d:boolean){palette=p;dark=d;if(p==='original')delete document.documentElement.dataset.palette;else document.documentElement.dataset.palette=p;document.documentElement.classList.toggle('dark',d);try{localStorage.setItem('drevanta-svelte-palette',p);localStorage.setItem('drevanta-svelte-mode',d?'dark':'light')}catch{}}</script><Heading title="Settings" subtitle="Account, appearance and server access preferences."/><div class="tabs">{#each ['Account','Appearance','Security','Panel access','SSH access'] as t}<button class="tab" class:active={tab===t} on:click={()=>tab=t}>{t}</button>{/each}</div>{#if tab==='Appearance'}<div class="stack"><section class="card"><div class="eyebrow">APPEARANCE · COLOR PALETTES</div><h2>Color palette studio</h2><p class="subtitle" style="margin-bottom:16px">All original Drevanta colorways.</p><div class="palette-grid">{#each palettes as p}<button class="palette-choice" class:selected={palette===p[0]} aria-pressed={palette===p[0]} on:click={()=>apply(p[0],dark)}><span class={'palette-swatch swatch-'+p[0]}></span><span class="palette-label">{p[1]}</span></button>{/each}</div></section><section class="card"><h3>Appearance preferences</h3><div class="setting-row"><span>Color mode</span><div class="row"><button class={'btn '+(!dark?'primary':'secondary')} on:click={()=>apply(palette,false)}>Light mode</button><button class={'btn '+(dark?'primary':'secondary')} on:click={()=>apply(palette,true)}>Dark mode</button></div></div></section></div>{:else}<section class="card stack"><h3>{tab}</h3>{#if tab==='Account'}<div class="row"><span class="avatar">AD</span><div><strong>Administrator</strong><small style="display:block">Server owner · development preview</small></div></div>{/if}<p class="subtitle">Real authentication and server access settings have not been implemented in this frontend milestone.</p></section>{/if}
